INSERT INTO quizzes (book_id, chapter, kind, title) VALUES (17, 13, 'theory', 'Quiz: Xen, ESXi, Clouds and microVMs');
INSERT INTO quiz_questions (book_id, chapter, ord, q, options, answer, expl) VALUES (17, 13, 0, 'What is Dom0 in Xen?', '["A guest machine without privileges", "A privileged machine that manages the system and holds the drivers", "Another name for the hypervisor", "A network interface"]', 1, 'The other guests are called DomU; this split shrinks the trusted part.');
INSERT INTO quiz_questions (book_id, chapter, ord, q, options, answer, expl) VALUES (17, 13, 1, 'What is moved to special cards in AWS Nitro?', '["Network, disks and security functions go to cards with their own processors", "Only the scheduler", "Guest images", "The whole hypervisor"]', 0, 'The host is left with the minimum: running guests on KVM.');
INSERT INTO quiz_questions (book_id, chapter, ord, q, options, answer, expl) VALUES (17, 13, 2, 'What is removed from a microVM for speed and security?', '["The network", "The guest kernel", "Firmware, PCI bus, video and USB", "Memory"]', 2, 'What remains is a handful of virtio devices, a socket, a serial port and reset.');
INSERT INTO quiz_questions (book_id, chapter, ord, q, options, answer, expl) VALUES (17, 13, 3, 'Why does a micro virtual machine start so fast?', '["It uses a faster processor", "It uses no memory", "It runs on a graphics card", "It loads the kernel directly, without firmware and bootloader, and maps snapshot memory lazily"]', 3, 'This is how functions in serverless services start in milliseconds.');
INSERT INTO quiz_questions (book_id, chapter, ord, q, options, answer, expl) VALUES (17, 13, 4, 'What is the jailer in Firecracker for?', '["For migration", "It confines the monitor process: cgroups, namespaces, chroot, dropped privileges, seccomp", "For loading the kernel", "For the network"]', 1, 'An escape has to get through several layers of protection in a row.');
